// Generated by vibelang from src/internal/EngineStateSchema.vibe; the migrate flow writes it again with each batch.
/**
 * The schema objects `DurableEngineState` creates outside the journal
 * migration, and the inventory of what porting them to another
 * dialect costs.
 *
 * Each durable package owns its migration ladder. Spawn edges and their GC
 * trigger moved into engine-store migration 0006. The remaining
 * statements are engine-store-owned storage created idempotently at
 * construction instead (issues #40/#41/#79/#81). That is a deliberate lane
 * boundary, not an oversight — but it left the statements invisible to the
 * pg-porting plan in the database roadmap, which
 * scoped only the journal migration's SQLite-specific DDL. Declaring them here
 * makes the inventory machine-readable: a test diffs the database's schema
 * objects across `make` against this list, so no engine-owned statement can
 * be added without appearing in the porting inventory (issue #92).
 *
 * @since 0.1.0
 */
import { isReadOnly } from "@smthrs/database/Dialect";
import * as Effect from "effect/Effect";
/**
 * The porting inventory: every engine-store-owned statement, in creation order.
 *
 * @since 0.1.0
 * @category constants
 */
export const statements = [
    {
        name: "flows_runs_stale_running_idx",
        reason: "Serves the stale-running sweep's per-tick predicate (issue #79): `status = 'running' AND heartbeat_at_ms < cutoff`, ordered by heartbeat. A partial index keeps it tiny — only live running rows appear.",
        // Partial indexes are valid Postgres since 9.5, so this one ports as-is.
        dialects: ["sqlite", "postgres"],
        ddl: `
      CREATE INDEX IF NOT EXISTS flows_runs_stale_running_idx
      ON flows_runs (heartbeat_at_ms)
      WHERE status = 'running'
    `
    }
];
/**
 * Creates the engine-store-owned objects, idempotently, in inventory order.
 *
 * `flows_runs` must already exist — every query in this service assumes a
 * migrated database, so `make` composes over one by construction. A read-only
 * client installs nothing.
 *
 * @since 0.1.0
 * @category constructors
 */
export const apply = (sql, writer) => 
// A read-only observer reads the schema it finds and installs nothing.
isReadOnly(sql) ? Effect.void : Effect.forEach(statements, (statement) => Effect.flatMap(installed(sql, statement), (found) => found ? Effect.void : writer.write(sql.unsafe(statement.ddl)).pipe(Effect.orDie)), { discard: true });
/**
 * Whether PostgreSQL already has `statement`'s object, read without a write
 * transaction: a Durable Object builds this service at every alarm, and the
 * write would take the schema's writer lock, which holds up every other
 * execution's writes. SQLite answers `false` and runs the idempotent
 * statement, as before.
 */
const installed = (sql, statement) => sql.onDialectOrElse({
    pg: () => sql `SELECT to_regclass(${statement.name}) IS NOT NULL AS found`.pipe(Effect.map(([row]) => row?.found === true), Effect.orDie),
    orElse: () => Effect.succeed(false)
});
